using System.Windows.Forms;
using System.Windows.Forms.DataVisualization.Charting;
namespace V10Lab {
 public sealed class RpmMotion {public double RPM,BoreMm,StrokeMm,RodMm,MeanMS,PeakMS,PeakAccelerationMS2,CamRPM;}
 public sealed class DynoDatum {public double RPM,TorqueNm,HP;}
 public static class RpmScience {
  public static RpmMotion Motion(Inputs p,double rpm){p.Validate();Inputs.Range(rpm,0,20000,"Geometry study RPM");double r=p.StrokeMm/2000,l=p.RodMm/1000,w=rpm*2*Math.PI/60,vmax=0,amax=0;for(int i=0;i<3600;i++){double t=i*Math.PI/1800,s=Math.Sin(t),c=Math.Cos(t),q=Math.Sqrt(l*l-r*r*s*s);double v=(r*s+r*r*s*c/q)*w,a=(r*c+r*r*(c*c-s*s)/q+Math.Pow(r,4)*s*s*c*c/(q*q*q))*w*w;vmax=Math.Max(vmax,Math.Abs(v));amax=Math.Max(amax,Math.Abs(a));}return new RpmMotion{RPM=rpm,BoreMm=p.BoreMm,StrokeMm=p.StrokeMm,RodMm=p.RodMm,MeanMS=2*p.StrokeMm/1000*rpm/60,PeakMS=vmax,PeakAccelerationMS2=amax,CamRPM=rpm/2};}
  public static Inputs ShortStroke(Inputs p,double stroke){Inputs q=p.Copy();q.StrokeMm=stroke;q.BoreMm=Math.Sqrt(4*Model.DisplacementM3(p)/(Math.PI*p.Cylinders*(stroke/1000)))*1000;q.Validate();return q;}
  public static List<DynoDatum> ParseDyno(string text){string[] rows=text.Replace("\r","").Split('\n').Where(s=>!String.IsNullOrWhiteSpace(s)).ToArray();if(rows.Length<2||rows.Length>10001)throw new ArgumentException("Provide a header and 1–10000 measured points.");string[] h=rows[0].Trim('\uFEFF').Split(',');if(h.Length<2||h.Length>3||h[0].Trim()!="rpm"||h[1].Trim()!="torque_Nm"||(h.Length==3&&h[2].Trim()!="hp"))throw new ArgumentException("CSV headers must be rpm,torque_Nm with optional third column hp (mechanical horsepower).");List<DynoDatum> data=new List<DynoDatum>();for(int i=1;i<rows.Length;i++){string[] f=rows[i].Split(',');if(f.Length!=h.Length)throw new ArgumentException("CSV column count at line "+(i+1));double rpm,torque;if(!double.TryParse(f[0],NumberStyles.Float,CultureInfo.InvariantCulture,out rpm)||!double.TryParse(f[1],NumberStyles.Float,CultureInfo.InvariantCulture,out torque))throw new ArgumentException("Numeric RPM/torque required at line "+(i+1));Inputs.Range(rpm,1,20000,"Measured RPM");Inputs.Range(torque,-5000,10000,"Measured torque N m");if(data.Count>0&&rpm<=data.Last().RPM)throw new ArgumentException("Measured RPM rows must be strictly increasing.");double hp=torque*rpm*2*Math.PI/60/Model.WattPerHP;if(f.Length==3){double supplied;if(!double.TryParse(f[2],NumberStyles.Float,CultureInfo.InvariantCulture,out supplied)||Double.IsInfinity(supplied)||Double.IsNaN(supplied)||Math.Abs(supplied-hp)>Math.Max(1,Math.Abs(hp)*.01))throw new ArgumentException("HP/torque/RPM mismatch at line "+(i+1)+". Check units; hp must agree within 1% or 1 hp.");}data.Add(new DynoDatum{RPM=rpm,TorqueNm=torque,HP=hp});}return data;}
  public static void Verify(){Inputs p=new Inputs();RpmMotion a=Motion(p,4000),b=Motion(p,8000);double r=p.StrokeMm/2000,l=p.RodMm/1000,w=8000*2*Math.PI/60;if(Math.Abs(b.PeakAccelerationMS2-r*(1+r/l)*w*w)>1e-7)throw new Exception("TDC acceleration identity.");if(Math.Abs(b.PeakMS/a.PeakMS-2)>1e-10||Math.Abs(b.PeakAccelerationMS2/a.PeakAccelerationMS2-4)>1e-10)throw new Exception("Velocity/acceleration RPM scaling.");double distance=0;for(int i=1;i<=3600;i++)distance+=Math.Abs(Model.PistonBelowTDC(i*.1,p)-Model.PistonBelowTDC((i-1)*.1,p));if(Math.Abs(distance-2*p.StrokeMm)>1e-8)throw new Exception("Full-cycle piston travel.");if(Math.Abs(b.MeanMS-distance/1000*8000/60)>1e-10)throw new Exception("Mean piston speed identity.");Inputs shorter=ShortStroke(p,85);if(Math.Abs(Model.DisplacementM3(shorter)-Model.DisplacementM3(p))>1e-12)throw new Exception("Short-stroke displacement preservation.");if(Motion(p,0).PeakMS!=0||Motion(p,0).PeakAccelerationMS2!=0)throw new Exception("Zero RPM motion.");var data=ParseDyno("rpm,torque_Nm,hp\n6000,100,"+(100*6000*2*Math.PI/60/Model.WattPerHP).ToString("R",CultureInfo.InvariantCulture));if(data.Count!=1)throw new Exception("Dyno parser.");foreach(string bad in new[]{"rpm,torque_Nm,hp\n6000,100,500","rpm,torque_Nm\n6000,NaN","rpm,torque_Nm\n6000,100\n5000,110","rpm,torque_Nm\n0,100"}){bool rejected=false;try{ParseDyno(bad);}catch(ArgumentException){rejected=true;}if(!rejected)throw new Exception("Invalid dyno data accepted.");}File.WriteAllText(Path.Combine(Lab.Root,"Evidence","RPM_Check.json"),Inputs.Json.Serialize(new{Status="PASS",Checks="TDC acceleration identity, RPM scaling, full-cycle travel/mean speed, displacement preservation, zero speed, measured CSV units/identity/nonfinite/order validation. Parser fixture is synthetic test-only data.",At8000=b,At10000=Motion(p,10000),ProvenRedline="UNKNOWN",MeasuredEngineDataLoaded=false}));}
 }
 public sealed partial class Lab {
  bool rpmSoftwareTest;TabPage rpmStudyTab;NumericUpDown studyRPM,meanSpeedCap;Label rpmSummary,measurementStatus;DataGridView motionGrid,rpmCaps;TextBox dynoSource;ComboBox dynoBasis;Chart measuredPlot;
  void BuildRpmStudy(){rpmStudyTab=Tab("RPM & real data");Panel scroll=new Panel{Dock=DockStyle.Fill,AutoScroll=true};rpmStudyTab.Controls.Add(scroll);TableLayoutPanel layout=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,ColumnCount=1,RowCount=8,Padding=new Padding(10),MinimumSize=new Size(600,0)};scroll.Controls.Add(layout);int[] heights={90,115,135,190,90,60,260,100};foreach(int height in heights)layout.RowStyles.Add(new RowStyle(SizeType.Absolute,height));layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));
   FlowLayoutPanel controls=new FlowLayoutPanel{Dock=DockStyle.Fill};layout.Controls.Add(controls,0,0);controls.Controls.Add(new Label{Text="Study RPM",Width=90,Padding=new Padding(0,7,0,0)});studyRPM=new NumericUpDown{Minimum=0,Maximum=20000,Increment=500,Value=8000,Width=90};controls.Controls.Add(studyRPM);controls.Controls.Add(new Label{Text="Assumed mean-speed cap m/s (0 = unknown)",Width=310,Padding=new Padding(0,7,0,0)});meanSpeedCap=new NumericUpDown{Minimum=0,Maximum=60,DecimalPlaces=1,Value=0,Width=75};controls.Controls.Add(meanSpeedCap);Button(controls,"Calculate RPM study",RunRpmStudy,true);Button(controls,"Read RPM notes",()=>OpenPath(Path.Combine(Root,"RPM_And_Real_Data.md")),false);
   rpmSummary=new Label{Dock=DockStyle.Fill,Font=new Font("Segoe UI",10,FontStyle.Bold),Padding=new Padding(5)};layout.Controls.Add(rpmSummary,0,1);motionGrid=Grid();motionGrid.ReadOnly=true;foreach(string h in new[]{"Geometry option","Bore mm","Stroke mm","Mean m/s","Peak m/s","Peak accel g","Cam RPM"})motionGrid.Columns.Add(h,h);motionGrid.Columns[0].FillWeight=220;layout.Controls.Add(motionGrid,0,2);
   rpmCaps=Grid();rpmCaps.SelectionMode=DataGridViewSelectionMode.CellSelect;rpmCaps.Columns.Add("component","Missing component limits");rpmCaps.Columns.Add("cap","RPM cap (0 = unknown)");rpmCaps.Columns.Add("source","Source / part / test reference");rpmCaps.Columns[0].ReadOnly=true;rpmCaps.Columns[2].FillWeight=200;foreach(string name in new[]{"Pistons / rods / rod bolts","Crankshaft / torsional vibration","Valvetrain / springs / followers","Bearings / lubrication","Induction / accessory drive","Transmission / flywheel"})rpmCaps.Rows.Add(name,0,"");layout.Controls.Add(rpmCaps,0,3);
   FlowLayoutPanel imports=new FlowLayoutPanel{Dock=DockStyle.Fill};layout.Controls.Add(imports,0,4);imports.Controls.Add(new Label{Text="Dyno source / test date / engine ID",Width=260,Padding=new Padding(0,7,0,0)});dynoSource=new TextBox{Width=400};imports.Controls.Add(dynoSource);dynoBasis=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=185};dynoBasis.Items.AddRange(new object[]{"Select measurement basis","Engine / crank dyno","Chassis / wheel dyno"});dynoBasis.SelectedIndex=0;imports.Controls.Add(dynoBasis);Button(imports,"Import measured dyno CSV",ImportDyno,false);Button(imports,"Create blank data template",()=>{string path=Path.Combine(Root,"Runs","Measured_Dyno_Template.csv");if(!File.Exists(path))File.WriteAllText(path,"rpm,torque_Nm,hp\r\n");OpenPath(Path.Combine(Root,"Runs"));},false);
   measurementStatus=new Label{Dock=DockStyle.Fill,Padding=new Padding(5),Text="MEASURED ENGINE DATA: 0 points loaded. Live HP remains an unvalidated model estimate.\nImported data is user supplied; this app cannot authenticate measurements. No automatic calibration."};layout.Controls.Add(measurementStatus,0,5);measuredPlot=NewChart("Torque-shaft RPM","Power (mechanical hp)");measuredPlot.Titles.Add("Import measured torque to compare with the current assumed model");layout.Controls.Add(measuredPlot,0,6);layout.Controls.Add(new Label{Dock=DockStyle.Fill,Padding=new Padding(5),Text="Geometry-only study range: 0–20,000 RPM; this is not a safe operating range. Performance calculations remain bounded to 7,000 RPM and use assumed VE/losses.\nStroke alternatives preserve displacement mathematically but require a new block, pistons, heads, clearances and structural/thermal development.\nNo mass, stress, fatigue, oil-film, spring dynamics, valve-float, resonance or turbo shaft-speed limit is solved. Zero component caps mean missing evidence."},0,7);RunRpmStudy();
  }
  void RunRpmStudy(){rpmCaps.EndEdit();List<double> supplied=new List<double>();int missing=0;foreach(DataGridViewRow row in rpmCaps.Rows){double cap;if(!Double.TryParse(Convert.ToString(row.Cells[1].Value),NumberStyles.Float,CultureInfo.InvariantCulture,out cap))throw new ArgumentException("RPM cap must be a number.");Inputs.Range(cap,0,20000,"Component RPM cap");if(cap==0)missing++;else{if(String.IsNullOrWhiteSpace(Convert.ToString(row.Cells[2].Value)))throw new ArgumentException("Give a part/test source for every nonzero component cap.");supplied.Add(cap);}}double n=(double)studyRPM.Value;var options=new[]{input.Copy(),RpmScience.ShortStroke(input,90),RpmScience.ShortStroke(input,85)};string[] names={"Current CAD geometry","90 mm stroke concept","85 mm stroke concept"};motionGrid.Rows.Clear();List<RpmMotion> motion=new List<RpmMotion>();for(int i=0;i<options.Length;i++){RpmMotion r=RpmScience.Motion(options[i],n);motion.Add(r);motionGrid.Rows.Add(names[i],r.BoreMm.ToString("F2"),r.StrokeMm.ToString("F3"),r.MeanMS.ToString("F2"),r.PeakMS.ToString("F2"),(r.PeakAccelerationMS2/9.80665).ToString("F0"),r.CamRPM.ToString("F0"));}string capText=supplied.Count==0?"No component RPM limits supplied.":"Lowest supplied limit: "+supplied.Min().ToString("F0")+" RPM; "+missing+" constraints still unknown. Source accuracy is unverified.";string speed=(double)meanSpeedCap.Value==0?"No mean-speed threshold assumed.":"Selected mean-speed threshold implies "+((double)meanSpeedCap.Value*60/(2*input.StrokeMm/1000)).ToString("F0")+" RPM; this is a study assumption, not a redline.";rpmSummary.Text="PROVEN MAXIMUM RPM: UNKNOWN\n"+capText+"\n"+speed+"\nDimensions come from the concept CAD; motion is calculated. No physical validation or HP extrapolation above 7,000 RPM.";string file=Path.Combine(Root,"Runs","RPM_Study_"+DateTime.UtcNow.ToString("yyyyMMdd_HHmmss_fff")+".json");File.WriteAllText(file,Inputs.Json.Serialize(new{Inputs=input.Copy(),RequestedRPM=n,AssumedMeanSpeedCapMS=meanSpeedCap.Value,SuppliedCaps=rpmCaps.Rows.Cast<DataGridViewRow>().Select(r=>new{Component=r.Cells[0].Value,RPM=r.Cells[1].Value,Source=r.Cells[2].Value}).ToArray(),Motion=motion,ProvenRedline="UNKNOWN",Scope="Rigid slider-crank geometry only; no safe RPM or engine-power claim"}));}
  void ImportDyno(){if(dynoBasis.SelectedIndex==0)throw new ArgumentException("Choose engine/crank or chassis/wheel dyno. They cannot be compared as equivalent measurements.");if(String.IsNullOrWhiteSpace(dynoSource.Text))throw new ArgumentException("Enter the dyno source, test date and engine ID before importing.");using(OpenFileDialog dialog=new OpenFileDialog{Filter="Measured dyno CSV (*.csv)|*.csv",InitialDirectory=Path.Combine(Root,"Runs")})if(dialog.ShowDialog()==DialogResult.OK)ImportDynoPath(dialog.FileName);}
  void ImportDynoPath(string filename){byte[] bytes=File.ReadAllBytes(filename);var data=RpmScience.ParseDyno(System.Text.Encoding.UTF8.GetString(bytes));measuredPlot.Series.Clear();Series measured=Line(measuredPlot,"Imported torque-derived HP ("+dynoBasis.Text+")",Orange),predicted=Line(measuredPlot,"Uncalibrated crank-HP model",Blue);double sum=0;int count=0;foreach(DynoDatum r in data){measured.Points.AddXY(r.RPM,r.HP);if(dynoBasis.SelectedIndex==1&&r.RPM<=7000){double hp=Model.Calculate(input,r.RPM,1,turbo.Checked,sc.Checked).HP;predicted.Points.AddXY(r.RPM,hp);sum+=(hp-r.HP)*(hp-r.HP);count++;}}measuredPlot.Titles.Clear();measuredPlot.Titles.Add("User-supplied shaft power; crank-data comparison only; not certified");string hash;using(SHA256 sha=SHA256.Create())hash=BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();string destination=rpmSoftwareTest?Path.Combine(Root,"Evidence","RPM_Synthetic_Test"):Path.Combine(Root,"Runs");Directory.CreateDirectory(destination);string stem=Path.Combine(destination,"Imported_Dyno_"+DateTime.UtcNow.ToString("yyyyMMdd_HHmmss_fff"));File.WriteAllBytes(stem+".csv",bytes);File.WriteAllText(stem+".json",Inputs.Json.Serialize(new{SyntheticSoftwareTest=rpmSoftwareTest,Source=dynoSource.Text,MeasurementBasis=dynoBasis.Text,OriginalFile=Path.GetFileName(filename),SHA256=hash,ImportedUTC=DateTime.UtcNow.ToString("o"),Points=data,ModelInputs=input.Copy(),Turbo=turbo.Checked,Supercharger=sc.Checked,FullThrottleComparison=true,ComparedPoints=count,RMSE_HP=count>0?(double?)Math.Sqrt(sum/count):null,Authenticity="User-supplied; not independently authenticated",Calibration="None; model assumptions unchanged"}));measurementStatus.Text=data.Count+" user-supplied points; "+count+" within model range. "+(count>0?"HP RMSE: "+Math.Sqrt(sum/count).ToString("F1"):dynoBasis.SelectedIndex==2?"Wheel data: no direct crank-HP comparison.":"No model comparison above 7,000 RPM.")+"\nSource: "+dynoSource.Text+". Snapshot saved; authenticity unverified. Current model remains uncalibrated.";}
  public void OpenRpmStudy(){tabs.SelectedTab=rpmStudyTab;RunRpmStudy();}
  public void RpmStudyCheck(){RpmScience.Verify();rpmSoftwareTest=true;string fixture=Path.Combine(Root,"Evidence","RPM_Synthetic_Fixture.csv");File.WriteAllText(fixture,"rpm,torque_Nm,hp\r\n6000,100,"+(100*6000*2*Math.PI/60/Model.WattPerHP).ToString("R",CultureInfo.InvariantCulture));dynoSource.Text="SYNTHETIC SOFTWARE TEST ONLY; not measured engine data";dynoBasis.SelectedIndex=1;ImportDynoPath(fixture);if(measuredPlot.Series[0].Points.Count!=1||measuredPlot.Series[1].Points.Count!=1)throw new Exception("Crank data comparison wiring.");dynoBasis.SelectedIndex=2;ImportDynoPath(fixture);if(measuredPlot.Series[1].Points.Count!=0||!measurementStatus.Text.Contains("Wheel data"))throw new Exception("Wheel data was compared with crank HP.");string[] snapshots=Directory.GetFiles(Path.Combine(Root,"Evidence","RPM_Synthetic_Test"),"*.json");if(snapshots.Length<2||!File.ReadAllText(snapshots.Last()).Contains("SHA256"))throw new Exception("Dyno provenance snapshot.");rpmSoftwareTest=false;dynoSource.Text="";dynoBasis.SelectedIndex=0;measuredPlot.Series.Clear();measurementStatus.Text="MEASURED ENGINE DATA: 0 points loaded. Test fixtures were synthetic and were cleared. Live HP is an unvalidated model estimate.";OpenRpmStudy();if(!rpmSummary.Text.Contains("UNKNOWN")||motionGrid.Rows.Count!=3||rpmCaps.Rows.Count!=6)throw new Exception("RPM study UI evidence state.");Application.DoEvents();using(Bitmap bmp=new Bitmap(Width,Height)){DrawToBitmap(bmp,new Rectangle(0,0,Width,Height));bmp.Save(Path.Combine(Root,"Evidence","RPM_Study.png"));}File.WriteAllText(Path.Combine(Root,"Evidence","RPM_UI_Check.txt"),"PASS: geometry study, separate bore/stroke options, six unknown component caps, proven redline UNKNOWN, no measured data fabricated, no power extrapolation. Math/parser checks in RPM_Check.json. Synthetic CSV-to-chart/provenance integration passed; wheel data excluded from crank-model comparison; all synthetic UI data cleared.");}
 }
